tool_calls:
sqlite /var/lib/ledger.db << 'EOF'
.headers on
SELECT * FROM txns ORDER BY txn_id;
SELECT '---';
SELECT * FROM balances ORDER BY account;
SELECT '--- integrity: balances minus computed sum of txns ---';
SELECT b.account, b.balance_cents, COALESCE(t.s,0) AS txn_sum, b.balance_cents - COALESCE(t.s,0) AS diff
FROM balances b LEFT JOIN (SELECT account, SUM(amount_cents) s FROM txns GROUP BY account) t
ON b.account = t.account;
SELECT '--- accounts in txns missing from balances (should be empty) ---';
SELECT DISTINCT account FROM txns WHERE account NOT IN (SELECT account FROM balances);
EOF

